def flowFile = session.get()
if (flowFile == null) return

try {
    ObjectMapper mapper = new ObjectMapper()

    // 1. 원본 데이터 가져오기
    String mappingData = flowFile.getAttribute("flowfile.mapping.data")
	String selectMenuSqMap = flowFile.getAttribute("flowfile.selectMenuSq.data")
 if (mappingData == null || mappingData.trim().isEmpty()) {
    log.error("mappingData attribute is missing or empty!")
    session.transfer(flowFile, REL_FAILURE)
    return
}    

if (selectMenuSqMap == null || selectMenuSqMap.trim().isEmpty()) {
    log.error("selectMenuSqMap attribute is missing or empty!")
    session.transfer(flowFile, REL_FAILURE)
    return
}
    // TypeReference 대신 List.class 사용
    List<Map<String, Object>> mappingDataListMap = mapper.readValue(mappingData, List.class)

    log.info("원본 데이터: " + mappingDataListMap)

    // TypeReference 대신 List.class 사용
    Map<String, Object> menuSqMap = mapper.readValue(selectMenuSqMap, Map.class)

    if (!menuSqMap) throw new Exception("분개 순번 데이터를 찾을 수 없습니다.")

    def menuSq = menuSqMap.get("menuSq")

    // 4. 원본 데이터에 매핑 적용
    mappingDataListMap.each { origin ->
    // 새 컬럼 menuSq 추가
    origin.menuSq = menuSq
  }
    def result = ""
    // 5. 결과 쓰기
    flowFile = session.write(flowFile) { inputStream, outputStream ->
